import 'dart:math' as math;

import 'gate_system.dart';
import 'track_graph.dart';
import 'track_path.dart';
import 'tram_physics.dart';
import 'turntable_movement.dart';
import 'turntable_switch_system.dart';
import 'turntable_turn.dart';

/// Per-frame state of one tram observed by [TramAiSystem].
typedef AiTramSnapshot = ({
  int index,
  TrackPath path,
  double trackDistance,
  double speed,
  double cruiseSpeed,
  bool isPlayerControlled,
  bool isRidingTurntable,
  bool isCrashed,
  math.Point<double> position,
});

/// Control output generated by [TramAiSystem] for one AI-driven tram.
typedef AiTramCommand = ({
  double throttle,
  bool shouldTurn,
  math.Point<double>? desiredDirection,
});

/// Pure-Dart tactical cruise and turntable-switching controller for AI (`GÉPI`) trams.
class TramAiSystem {
  /// Creates an AI controller bound to [graph], [paths], and [switches].
  TramAiSystem({
    required this.graph,
    required this.paths,
    required this.switches,
    this.gates,
    this.patrolSwitchIntervalSec = 4.0,
  });

  /// Vehicle linear acceleration (px/s²) shared via [TramPhysics].
  static const double vehicleAcceleration = TramPhysics.acceleration;

  /// Per-second velocity retention factor shared via [TramPhysics].
  static const double vehicleDrag = TramPhysics.drag;

  /// Half the tram hull length (px) shared via [TramPhysics].
  static const double vehicleHalfLength = TramPhysics.halfLength;

  /// Remaining distance (px) to an open-track hazard that triggers panic braking.
  static const double panicBrakeLookaheadPx = 75;

  /// Remaining distance (px) to an open-track hazard that triggers evasive switching.
  static const double evadeHazardLookaheadPx = 180;

  static const double _patrolCenterWindowPx = 24;
  static const double _evasiveCooldownSec = 1.0;
  static const String _revSuffix = '_rev';

  /// Level track topology for resolving open-segment end hazards.
  final TrackGraph graph;

  /// Base segment polylines keyed by segment id.
  final Map<String, TrackPath> paths;

  /// Turntable switch catalog used to evaluate boardable turns.
  final TurntableSwitchSystem switches;

  /// Optional track-barrier gate system opened ahead of AI trams via SHIFT.
  final GateSystem? gates;

  /// Cooldown (seconds) between routine patrol switches of one AI tram.
  final double patrolSwitchIntervalSec;

  final Map<int, double> _switchCooldowns = {};

  /// Advances AI timers by [dt] and returns commands keyed by tram `index`
  /// for active unmanned trams (`!isPlayerControlled && cruiseSpeed != 0`).
  Map<int, AiTramCommand> step(
    double dt,
    List<AiTramSnapshot> trams, {
    Iterable<math.Point<double>> occupiedCenters = const [],
  }) {
    _advanceCooldowns(dt);
    final playerBaseIds = <String>{
      for (final t in trams)
        if (t.isPlayerControlled && !t.isCrashed) _baseId(t.path.name),
    };
    final commands = <int, AiTramCommand>{};
    for (final tram in trams) {
      if (tram.isPlayerControlled || tram.cruiseSpeed == 0) continue;
      if (tram.isCrashed || tram.isRidingTurntable) continue;
      commands[tram.index] = _commandFor(tram, playerBaseIds, occupiedCenters);
    }
    return commands;
  }

  void _advanceCooldowns(double dt) {
    for (final entry in _switchCooldowns.entries.toList()) {
      final remaining = entry.value - dt;
      if (remaining <= 0) {
        _switchCooldowns.remove(entry.key);
      } else {
        _switchCooldowns[entry.key] = remaining;
      }
    }
  }

  AiTramCommand _commandFor(
    AiTramSnapshot tram,
    Set<String> playerBaseIds,
    Iterable<math.Point<double>> occupiedCenters,
  ) {
    var throttle = _cruiseThrottle(tram.speed, tram.cruiseSpeed);
    final gateDist = gates?.closedGateDistanceAhead(
      tram.path,
      tram.trackDistance,
      tram.speed,
    );
    if (gateDist != null && gateDist <= 95.0) {
      if (!_switchCooldowns.containsKey(tram.index)) {
        _switchCooldowns[tram.index] = _evasiveCooldownSec;
        return (throttle: throttle, shouldTurn: true, desiredDirection: null);
      }
      if (gateDist <= panicBrakeLookaheadPx) {
        throttle = tram.speed >= 0 ? -1.0 : 1.0;
      }
    }
    final hazardDist = _hazardDistanceAhead(tram);
    final candidates = _boardableTurns(tram, occupiedCenters);

    if (hazardDist != null && hazardDist <= evadeHazardLookaheadPx) {
      final escape = _firstSafeTurn(candidates, tram.speed);
      if (escape != null) {
        _switchCooldowns[tram.index] = _evasiveCooldownSec;
        return (
          throttle: throttle,
          shouldTurn: true,
          desiredDirection: _exitDirection(escape),
        );
      }
    }

    if (hazardDist != null && hazardDist <= panicBrakeLookaheadPx) {
      throttle = tram.speed >= 0 ? -1.0 : 1.0;
    }

    if (!_switchCooldowns.containsKey(tram.index)) {
      final patrol = _pickPatrolTurn(tram, candidates, playerBaseIds);
      if (patrol != null) {
        _switchCooldowns[tram.index] = patrolSwitchIntervalSec;
        return (
          throttle: throttle,
          shouldTurn: true,
          desiredDirection: _exitDirection(patrol),
        );
      }
    }

    return (throttle: throttle, shouldTurn: false, desiredDirection: null);
  }

  static double _cruiseThrottle(double speed, double cruiseSpeed) {
    final ff = cruiseSpeed * (-math.log(vehicleDrag)) / vehicleAcceleration;
    final kp = (cruiseSpeed - speed) / 40.0;
    return (ff + kp).clamp(-1.0, 1.0);
  }

  double? _hazardDistanceAhead(AiTramSnapshot tram) {
    if (tram.speed == 0) return null;
    final isRev = tram.path.name.endsWith(_revSuffix);
    final baseId = _baseId(tram.path.name);
    final basePath = paths[baseId];
    if (basePath == null || basePath.isClosed) return null;
    if (!graph.segments.containsKey(baseId)) return null;

    final forwardHazard = graph.advance(baseId).end != TrackEnd.connected;
    if (!isRev) {
      if (tram.speed > 0) {
        return forwardHazard
            ? math.max(0.0, basePath.length - tram.trackDistance)
            : null;
      }
      return math.max(0.0, tram.trackDistance);
    }
    if (tram.speed > 0) {
      return math.max(0.0, basePath.length - tram.trackDistance);
    }
    return forwardHazard ? math.max(0.0, tram.trackDistance) : null;
  }

  List<TurntableTurn> _boardableTurns(
    AiTramSnapshot tram,
    Iterable<math.Point<double>> occupiedCenters,
  ) => [
    for (final turn in switches.turns)
      if (!turn.autoBoard &&
          !_isOccupied(turn.center, occupiedCenters) &&
          turn.board(
                tram.path,
                tram.trackDistance,
                tram.speed,
                vehicleHalfLength,
              ) !=
              null)
        turn,
  ];

  TurntableTurn? _firstSafeTurn(List<TurntableTurn> candidates, double speed) {
    for (final turn in candidates) {
      if (_isSafeExit(turn.to, speed)) return turn;
    }
    return null;
  }

  TurntableTurn? _pickPatrolTurn(
    AiTramSnapshot tram,
    List<TurntableTurn> candidates,
    Set<String> playerBaseIds,
  ) {
    TurntableTurn? fallback;
    for (final turn in candidates) {
      if (turn.movement == TurntableMovement.reverse) continue;
      final offset = turn.offsetOf(tram.path, tram.trackDistance);
      if (offset == null || offset.abs() > _patrolCenterWindowPx) continue;
      if (!_isSafeExit(turn.to, tram.speed)) continue;
      if (playerBaseIds.contains(_baseId(turn.to.name))) return turn;
      fallback ??= turn;
    }
    return fallback;
  }

  bool _isSafeExit(TrackPath exitPath, double speed) {
    final isRev = exitPath.name.endsWith(_revSuffix);
    final baseId = _baseId(exitPath.name);
    final basePath = paths[baseId];
    if (basePath == null) return false;
    if (basePath.isClosed) return true;
    if (!graph.segments.containsKey(baseId)) return false;
    final headsForward = (!isRev && speed >= 0) || (isRev && speed < 0);
    return headsForward && graph.advance(baseId).end == TrackEnd.connected;
  }

  static bool _isOccupied(
    math.Point<double> center,
    Iterable<math.Point<double>> occupiedCenters,
  ) => occupiedCenters.any((c) => c.distanceTo(center) < 1.0);

  static math.Point<double> _exitDirection(TurntableTurn turn) {
    final h = turn.to.headingAt(turn.toAlong);
    return math.Point(math.sin(h), -math.cos(h));
  }

  static String _baseId(String name) => name.endsWith(_revSuffix)
      ? name.substring(0, name.length - _revSuffix.length)
      : name;
}
